// en/fi/sv texts for assistantAppGuideMore.cjs. Button and tab names are the ones the localized UI shows (src/lib/translations*.json); Hubert's own sentences are written natural, not translated word for word.
// Merged into LOCALIZED by assistantAppGuideI18n.cjs: a module entry here adds its tasks to the module that already exists there.
const MORE_LOCALIZED = {
  en: {
    modules: {
      hub: {
        title: 'Front page',
        summary: 'The start page with the module tiles, today\'s overview, announcements from managers and the bell with notifications.',
        where: 'The front page opens when you log in. Use the back button or Escape to return to it.',
        tasks: {
          'read-announcements': { title: 'Read or hide an announcement', where: 'The front page, at the top above the module tiles.', steps: ['Announcements from managers are at the top of the front page, above the module tiles. They show a title, the text, who wrote it and how long ago.', 'Click the cross on an announcement to hide it. It is only hidden for you and does not come back.', 'If you have been away for a while, the "Since last time" window mentions new announcements.'], notes: 'Only managers can write new announcements and delete them for everyone. Announcements are separate from Email System.' },
          'post-announcement': { title: 'Post an announcement to everyone', where: 'The front page, at the top above the module tiles.', steps: ['Click "New announcement" at the top of the front page. The button is only shown to managers.', 'Write a title and a message to all employees.', 'Click "Post". The announcement is shown to everyone in the team straight away.'], notes: 'Delete an announcement for everyone with the trash can on it. Employees can only hide an announcement for themselves.' },
          'notification-bell': { title: 'Notifications (the bell)', where: 'The bell at the top right of the front page.', steps: ['The bell shows a number when something needs your attention, e.g. new emails, updated notes, replies about vacation, guides due for review, birthdays, to-dos, improvement suggestions, links to approve, high-fives and Multiplayer challenges.', 'Click the bell to see the list. Click a line to go straight to the right place in the app. The line then disappears from the bell.', 'Click the cross on a line to delete it, or "Clear all" to delete the whole list. A deleted notification does not come back. If it says "You\'re all caught up", nothing needs your attention.'], notes: 'All notifications are collected here, also from Improvements and Multiplayer. The same list can also be shown as a Windows notification (profile menu > "Settings"). With more than 9 it says "9+".' },
          'send-high-five': { title: 'Send a high-five to a colleague', where: 'The front page: the "High-fives" card.', steps: ['Find the "High-fives" card on the front page and click "Send high-five".', 'Search for a colleague by name or team and pick them. You can send to any approved colleague in any team, but not to yourself.', 'Pick an emoji and write a short message of up to 200 characters.', 'Click "Send high-five". The recipient gets it in the bell (and as a Windows notification if that is on).'], notes: 'The card shows the latest high-fives you received and the latest in your team. You can send at most 20 high-fives an hour. Hide the card under "Customize dashboard". You can also ask Hubert, e.g. «send a high-five to Anne for the help» – you confirm it yourself before it is sent.' },
          'quick-navigation': { title: 'Switch module with the keyboard (Ctrl+K)', where: 'Anywhere in the app.', steps: ['Press Ctrl+K (Cmd+K on a Mac). Press it again to close.', 'Type in the "Search modules, guides, colleagues, notes…" field. You can search modules, guides, Knowledge Base articles, links, colleagues, notes, to-dos, improvements and your own messages. Results are grouped, and each row shows what it is, e.g. "Guide · TCD" or "Note · shared".', 'Choose a result with the arrow keys and press Enter (or click). It opens the right place: the guide or article, the note, the colleague in Team Overview, the to-do, the improvement or the message. Choosing a module, e.g. Calendar or Meal Plan, opens that module. "Home" takes you back to the front page.'], notes: 'You only see what you already have access to: your own private notes, to-dos and messages, plus the team\'s shared notes and guides. Managers also see Manager Panel and Admin Panel. A creator also sees Creator Panel and can switch team under "Switch team". Escape closes the search.' },
          'switch-hub': { title: 'Switch hub when you are manager in several teams', where: 'The front page: the "Switch hub" button next to the team name, the profile menu at the top right, or Ctrl+K.', steps: ['If you were given manager access in teams other than your own, "Choose your hub" appears after login. Click "Open" on the hub you want to work in. The one you chose last time is selected.', 'To switch later, click "Switch hub" on the front page or in the profile menu, or press Ctrl+K and choose "Switch to: <team>". You do not have to log out.', 'A red number next to "Switch hub" shows how many user and vacation requests are waiting for you in your other hubs.'], notes: 'In a team other than your own you are a manager with the same rights as the team\'s own managers, but you are not listed in their shift schedule, vacation overview or team list. Your personal things (language, theme, front page, own To Do) follow you. Only the creator can give or remove the access, and the team\'s managers can see you under "Managers from other teams" in Manager Panel.' },
          'my-week': { title: 'My week on the front page', where: 'The front page: the "My week" card, at the top.', steps: ['Find the "My week" card at the top of the front page. It shows your own week from Monday to Sunday, and today is highlighted.', 'Each day lists your shifts (also recurring ones), vacation, days off and parental leave, vacation requests that are not approved yet (marked "pending"), sick leave, home office, to-dos and team to-dos that are due, guides you must review and improvements with a deadline. A day without plans shows a dash. If the whole week is empty, it says "No plans this week".', 'Click a line to go straight to the right place: Shift Schedule, Calendar, To Do, Guide Library or Improvements.', 'To hide the card, click "Customize dashboard" and switch "My week" off. That is also where you choose the size: Small shows today and the next two days, Standard the whole week, and Large the whole week with more detail.'], notes: 'The card only shows your own things, not your colleagues\', and never the comments on shifts. A deadline that has passed is shown on today and marked "overdue". The card always sits at the top, and your choice is saved to your own account.' },
          'morning-briefing': { title: 'Hubert\'s morning briefing', where: 'The Hubert chat (the "Ask Hubert" button at the bottom right).', steps: ['Open Hubert (the "Ask Hubert" button at the bottom right, or Ctrl+S) the first time each day. Hubert then puts a short overview at the top of the chat by itself.', 'The overview shows your shifts today (also recurring ones), whether you are on vacation, sick or working from home, your own to-dos and team to-dos that are due today or overdue, who in the team is away or working from home (names only, never reasons), guides you must review and improvements with a deadline this week. Empty parts are left out.', 'To see it again, write "good morning" or "what\'s on today?" to Hubert.'], notes: 'The overview only shows your own things and the team\'s absence. It appears automatically at most once a day on your own PC.' },
          'customize-dashboard': { title: 'Customize the dashboard on the front page', where: 'The front page: the "Customize dashboard" button.', steps: ['Click "Customize dashboard" at the top of the front page.', 'Switch the cards you want to see on or off: My week, Team tasks today, Team status today, High-fives, Off today, Today\'s meal, Sick today, Off in Supply Chain, Home office in Supply Chain and Sick in Supply Chain.', 'Choose the size of each card: Small, Standard or Large.', 'Click "Done". "Reset" restores the default setup.'], notes: 'Your choice is saved to your own account and does not affect anyone else.' },
          'since-last-time': { title: 'The "Since last time" window', where: 'It opens by itself when you log in.', steps: ['If something has happened since your last visit, the "Since last time" window opens by itself when you log in.', 'It shows new emails, replies to your vacation requests, shared notes that have been updated and new announcements.', 'Click a line to go straight to the right module, or close the window.'], notes: 'The window looks back 30 days at most, and if there is nothing new it does not open. It is not shown the first time you log in.' },
          'whats-new': { title: 'What\'s new after an update', where: 'It opens by itself the first time you start the app after an update.', steps: ['The first time you start the app after an update, the "What\'s new in Supply Chain Hub" window opens. It briefly shows what is new since the version you last saw.', 'Click "Great, thanks!" to close it.', 'The version number is at the bottom left of the front page.'], notes: 'The window is shown only once per computer for each new version.' },
        },
      },
      admin: {
        title: 'Admin Panel',
        summary: 'Administration of users, employees, task types and sick leave for the team.',
        where: 'Open the profile menu at the top right ("My account") and choose "Admin Panel". It is only shown to managers.',
        tasks: {
          'admin-users': { title: 'View and edit users in Admin Panel', steps: ['Open Admin Panel and choose the "Users" tab. You see all users in the team.', 'Change a user\'s role (user or manager) in the list.', 'Click "Delete user" to remove a user. It cannot be undone.'], notes: 'The role of the creator user cannot be changed, and the creator user cannot be deleted.' },
          'admin-employees': { title: 'Add employees and task types in Admin Panel', steps: ['Open Admin Panel and choose the "Employees & Tasks" tab.', 'Click "Add Employee", enter full name, email, password and role, and click "Create Employee". The email cannot be changed afterwards.', 'Click "Add Task" for a new task type: enter the name, choose a colour and click "Create Task". The task can then be assigned in Shift Schedule.'], notes: 'If you delete a task, all shifts assigned to it are removed.' },
        },
      },
      creator: {
        title: 'Creator Panel',
        summary: 'Management of all teams: create teams and users, highscores, app updates and data storage.',
        where: 'Open the profile menu at the top right ("My account") and choose "Creator Panel". It is only shown to a creator.',
        tasks: {
          'manage-teams': { title: 'Create and edit teams and users', steps: ['Open Creator Panel and choose the "Teams" tab. All registered teams are listed with their managers.', 'Click "Create team", enter a team name and a short code (letters and numbers, used as the folder name), and save.', 'Click "Edit team" to change the name or abbreviation. The team\'s data folder is not moved.', 'Click "Create user", choose the team, enter name, email, password and role, and click "Create user".'] },
          'switch-team': { title: 'Switch team', steps: ['Press Ctrl+K (Cmd+K on a Mac).', 'Choose "Switch to: <team>" under "Switch team". You land on the front page in the chosen team.'], notes: 'A creator can switch to every team. Managers with access to several hubs switch under "Switch hub".' },
          'cross-team-managers': { title: 'Make a person manager in other teams', steps: ['Open Creator Panel, the "Teams" tab, and find "Managers across teams".', 'Click "Add", search for the person by name or e-mail, and tick the teams the person should be manager in. The person\'s own team cannot be chosen.', 'Click "Save". The next time the person logs in, they can choose a hub.', 'Click the pencil to change the teams, or the trash can to remove all access.'], notes: 'The person stays in their own team with their own password and is not listed in the other team. If you remove the access while the person is in that hub, they are sent home to their own team within a minute.' },
          'edit-highscores': { title: 'Edit or delete a highscore', steps: ['Open Creator Panel and choose the "Arcade" tab. Choose the game.', 'Click the pencil on a score to change the score or level, and click "Save changes".', 'Click the trash can and confirm to delete the score. "Delete all old highscores" clears highscores from an old game version.'], notes: 'Deleting a score cannot be undone.' },
          'publish-update': { title: 'Publish an app update', steps: ['Open Creator Panel and choose the "Data Storage" tab. Under "App Updates" you select the new app package (.zip) and enter the version number, e.g. 1.2.1.', 'Optionally write release notes, which are shown in the update window, and click "Publish update".', 'All clients are notified within 15 minutes. Under "Users\' App Versions" you see which version each user runs and can force a specific version.'] },
          'data-backup': { title: 'Data folder and backup', steps: ['Open Creator Panel and choose the "Data Storage" tab.', 'Under "Current data folder" you see where the app\'s data is kept. Click "Choose data folder…" to point to a fixed folder, e.g. on a network drive.', 'Click "Export backup" to save everything in one file. "Import backup…" and "Restore data" put the data back, and existing data with the same names is overwritten.'], notes: 'You do not lose data by updating the app. A backup is useful if you move to a new computer.' },
        },
      },
      calendar: {
        tasks: {
          'single-day-off': { title: 'Request a single day off', steps: ['Open Calendar and click "Request a day off".', 'Choose the date. Only weekdays can be chosen, and you can write a comment.', 'Click "Submit request".'], notes: 'The request goes to the team managers and awaits approval, just like a vacation request.' },
        },
      },
      meals: {
        tasks: {
          'view-meal-plan': { title: 'View the meal plan', steps: ['Open Meal Plan. The menus for the week from Monday to Friday are shown.', 'Change week with the arrows, or click "Go to current week" to jump back to this week.', 'Under "Previous meal plans" you can see menus from earlier weeks.'], notes: 'If you just want to know what is for lunch, ask me, e.g. “What is for lunch tomorrow?”.' },
          'edit-meal-plan': { title: 'Edit the meal plan', steps: ['Open Meal Plan and click "Edit meal plan".', 'Write the menu for each day from Monday to Friday.', 'Click "Save". "Clear week" empties the whole week\'s menu, and "Cancel" discards the changes.'], notes: 'The meal plan is shared by the team and can be edited by everyone in the team.' },
        },
      },
      notebook: {
        tasks: {
          'edit-note': { title: 'Edit, pin or delete a note', steps: ['Open Notebook and find the note under "Shared Notes" or "Personal Notes".', 'Click the pencil to edit the note, or the trash can to delete it. You confirm the deletion, and it cannot be undone.', 'Click the pin to keep the note at the top of the list.'], notes: 'Only the person who wrote a note can edit or delete it.' },
          'find-note': { title: 'Find a note', steps: ['Open Notebook and type in the search field ("Search by title or content...").', 'Click a tag to show only notes with that tag. Click again to remove the filter.'], notes: 'When a colleague changes a shared note you wrote, it arrives in the bell on the Hub (Notebook has no bell of its own).' },
        },
      },
      email: {
        tasks: {
          'mail-folders': { title: 'Create a folder and move an email', steps: ['Open Email System and click the plus button next to "Folders" in the menu on the left.', 'Type the folder name, choose a colour and save.', 'Open an email and click "Move to folder" to put it in a folder. The folder is listed in the menu under "Folders".'] },
          'mail-filter': { title: 'Filter emails by date or sender', steps: ['Open Email System and choose "Inbox" or "Sent".', 'Use the filters "Select period" (All, Today, Last week, Last month) and "Select sender" (in Sent "Select recipient").'] },
        },
      },
      team: {
        tasks: {
          'other-teams': { title: 'See colleagues in other teams', steps: ['Open Team Overview. Your own team is at the top.', 'Further down, under "Other teams in Supply Chain", you can see the members of the other teams.'], notes: 'You only see who they are. Other teams\' notes and tasks are not open to you, and you cannot open their shift schedule in the Hub – but you can ask me about a colleague\'s shifts, e.g. «What is Frederik Torp doing this week?».' },
        },
      },
      guides: {
        tasks: {
          'manage-categories': { title: 'Manage guide categories', steps: ['Open Guide Library and click "Manage categories".', 'Type a name under "Add new category", or edit and delete existing categories.'], notes: 'The "General" category cannot be edited or deleted, and a category that is in use cannot be deleted.' },
          'export-library': { title: 'Export the guide library', steps: ['Open Guide Library and click "Export library".', 'Click "Choose folder" and point to a local folder or a network drive.', 'Click "Export all guides". Each guide is saved as a Word file (.docx) in a folder per category.'] },
        },
      },
      manager: {
        tasks: {
          'bulk-approve': { title: 'Approve several vacation requests at once', steps: ['Open Manager Panel and choose the "Requests" tab.', 'Tick the requests you want to handle, or click "Select all".', 'Click "Approve selected" or "Reject selected". You can also approve or reject a single request with "Approve" and "Reject".'], notes: 'The employees are notified of the decision automatically.' },
          'manage-vacations': { title: 'View, edit and delete vacations in Vacation Overview', steps: ['Open Manager Panel and choose the "Vacation Overview" tab.', 'Filter with "All", "Pending" or "Approved".', 'Click the edit button to change dates, comment or type (vacation or parental leave). Click the trash can and confirm to delete.', '"Grant Vacation/Day Off" at the top gives an employee vacation or a day off directly.'], notes: 'The employee is notified when a manager has edited or deleted a vacation.' },
          'manage-birthdays': { title: 'Register a birthday', steps: ['Open Manager Panel and choose the "Birthdays" tab.', 'Click the employee, and click "Add birthday". Choose the date and save.', 'In the same place you can edit a birthday or delete it with "Delete birthday".'], notes: 'The birthday is shown in the vacation calendar and celebrated automatically in the app. It can also be entered when you create a new employee.' },
          'access-requests': { title: 'Handle access requests from other teams', steps: ['Open Manager Panel and choose the "Guide Access" tab.', 'Under "Guide Access Requests" and "Knowledge Base Access Requests" you see the pending requests from other teams.', 'Click "Approve" or "Reject".'], notes: 'An approval grants 2 days of access to the actual content.' },
          'onboard-user': { title: 'Create a new employee (onboarding)', steps: ['Open Manager Panel, choose the "Permissions" tab and click "Onboarding".', 'Step 1 (account): enter full name, work email, phone and a temporary password (at least 6 characters), and choose a role.', 'Step 2 (birthday): choose the date of birth. The step is optional and can be skipped.', 'Step 3 (confirm): check the details and click "Create Employee".'], notes: 'The account is approved automatically, and the employee receives a welcome email in Supply Chain Hub. Give the employee the temporary password.' },
          'offboard-user': { title: 'Offboard an employee', steps: ['Open Manager Panel, choose the "Permissions" tab and click "Offboarding".', 'Choose the employee. You get a preview of what will be cleaned up: account, shift assignments, birthday and pending vacation requests.', 'Confirm and click "Offboard Employee". It cannot be undone.'], notes: 'Vacation and sick history is kept. The employee loses access to Supply Chain Hub, and all shifts are removed from the shift schedule.' },
        },
      },
    },
  },
  fi: {
    modules: {
      hub: {
        title: 'Etusivu',
        summary: 'Aloitussivu, jolla ovat moduuliruudut, päivän yhteenveto, esihenkilöiden ilmoitukset ja ilmoituskello.',
        where: 'Etusivu avautuu, kun kirjaudut sisään. Pääset takaisin siihen paluupainikkeella tai Escape-näppäimellä.',
        tasks: {
          'read-announcements': { title: 'Lue tai piilota ilmoitus', where: 'Etusivu, ylhäällä moduuliruutujen yläpuolella.', steps: ['Esihenkilöiden ilmoitukset ovat etusivun yläosassa moduuliruutujen yläpuolella. Niistä näkyvät otsikko, teksti, kirjoittaja ja se, kuinka kauan sitten ilmoitus on kirjoitettu.', 'Piilota ilmoitus napsauttamalla sen rastia. Ilmoitus piilotetaan vain sinulta, eikä se palaa.', 'Jos olet ollut pois jonkin aikaa, "Viime kerrasta lähtien" -ikkuna kertoo uusista ilmoituksista.'], notes: 'Vain esihenkilöt voivat kirjoittaa uusia ilmoituksia ja poistaa niitä kaikilta. Ilmoitukset ovat erillään Sähköpostijärjestelmästä.' },
          'post-announcement': { title: 'Kirjoita ilmoitus kaikille', where: 'Etusivu, ylhäällä moduuliruutujen yläpuolella.', steps: ['Napsauta etusivun yläosassa "Uusi ilmoitus". Painike näkyy vain esihenkilöille.', 'Kirjoita otsikko ja viesti kaikille työntekijöille.', 'Napsauta "Posti". Ilmoitus näkyy heti kaikille tiimissä.'], notes: 'Poistat ilmoituksen kaikilta ilmoituksen roskakorikuvakkeesta. Työntekijät voivat piilottaa ilmoituksen vain itseltään.' },
          'notification-bell': { title: 'Ilmoitukset (kello)', where: 'Kello etusivun oikeassa yläkulmassa.', steps: ['Kello näyttää numeron, kun jokin vaatii huomiotasi, esimerkiksi uudet sähköpostit, päivitetyt muistiinpanot, lomapyyntöjen vastaukset, tarkistettavat oppaat, syntymäpäivät, to-do-tehtävät, parannusehdotukset, hyväksyttävät linkit, high five -kiitokset ja Multiplayer-haasteet.', 'Napsauta kelloa nähdäksesi luettelon. Napsauta riviä päästäksesi suoraan oikeaan paikkaan sovelluksessa. Rivi katoaa sen jälkeen kellosta.', 'Poista rivi napsauttamalla sen rastia tai koko luettelo valinnalla "Tyhjennä kaikki". Poistettu ilmoitus ei palaa. Jos luettelo on tyhjä, mikään ei kaipaa huomiotasi.'], notes: 'Kaikki ilmoitukset kootaan tähän, myös Parannuksista ja Multiplayerista. Sama luettelo voidaan näyttää myös Windows-ilmoituksena (profiilivalikko > "Asetukset"). Jos rivejä on yli 9, kuvakkeessa lukee "9+".' },
          'send-high-five': { title: 'Lähetä high five kollegalle', where: 'Etusivu: kortti "High five -kiitokset".', steps: ['Etsi etusivulta kortti "High five -kiitokset" ja paina "Lähetä high five".', 'Hae kollega nimellä tai tiimillä ja valitse hänet. Voit lähettää kenelle tahansa hyväksytylle kollegalle missä tahansa tiimissä, mutta et itsellesi.', 'Valitse emoji ja kirjoita lyhyt viesti, enintään 200 merkkiä.', 'Paina "Lähetä high five". Vastaanottaja saa sen kelloon (ja Windows-ilmoituksena, jos se on päällä).'], notes: 'Kortti näyttää viimeisimmät saamasi high five -kiitokset ja tiimisi viimeisimmät. Voit lähettää enintään 20 high fivea tunnissa. Kortin voi piilottaa kohdassa "Muokkaa koontinäyttöä". Voit myös pyytää Hubertia, esim. «lähetä high five Annelle» – vahvistat sen itse ennen lähettämistä.' },
          'quick-navigation': { title: 'Vaihda moduulia näppäimistöllä (Ctrl+K)', where: 'Missä tahansa sovelluksessa.', steps: ['Paina Ctrl+K (Macilla Cmd+K). Sulje painamalla uudelleen.', 'Kirjoita kenttään "Etsi moduuleista, oppaista, kollegoista, muistiinpanoista…". Voit hakea moduuleja, oppaita, Knowledge Base -artikkeleita, linkkejä, kollegoita, muistiinpanoja, to-do-tehtäviä, parannuksia ja omia viestejäsi. Tulokset on ryhmitelty, ja jokaisella rivillä näkyy, mikä se on, esimerkiksi "Opas · TCD" tai "Muistiinpano · jaettu".', 'Valitse tulos nuolinäppäimillä ja paina Enter (tai napsauta). Oikea paikka avautuu: opas tai artikkeli, muistiinpano, kollega Ryhmän yleiskatsauksessa, to-do, parannus tai viesti. Jos valitset moduulin, esimerkiksi Kalenterin tai Ateriasuunnitelman, moduuli avautuu. "Alkuun" vie takaisin etusivulle.'], notes: 'Näet vain sen, mihin sinulla jo on pääsy: omat yksityiset muistiinpanosi, to-do-tehtäväsi ja viestisi sekä tiimin jaetut muistiinpanot ja oppaat. Esihenkilöt näkevät myös Manager Panelin ja Admin Panelin. Creator näkee myös Creator Panelin ja voi vaihtaa tiimiä kohdasta "Vaihtoryhmä". Escape sulkee haun.' },
          'switch-hub': { title: 'Vaihda hubia, kun olet esihenkilö useassa tiimissä', where: 'Etusivu: painike "Vaihda hubia" tiimin nimen vieressä, profiilivalikko oikealla ylhäällä tai Ctrl+K.', steps: ['Jos sinulle on annettu esihenkilöoikeus muissa kuin omassa tiimissäsi, "Valitse hubisi" tulee näkyviin kirjautumisen jälkeen. Napsauta "Avaa" sen hubin kohdalla, jossa haluat työskennellä. Viimeksi valitsemasi on valittuna.', 'Vaihtaaksesi myöhemmin napsauta "Vaihda hubia" etusivulla tai profiilivalikossa, tai paina Ctrl+K ja valitse "Vaihda kohteeseen: <tiimi>". Sinun ei tarvitse kirjautua ulos.', 'Punainen numero "Vaihda hubia" -kohdan vieressä kertoo, montako käyttäjä- ja lomapyyntöä odottaa sinua muissa hubeissasi.'], notes: 'Muussa kuin omassa tiimissäsi olet esihenkilö samoin oikeuksin kuin tiimin omat esihenkilöt, mutta et näy heidän vuorolistassaan, lomakatsauksessaan tai tiimilistassaan. Henkilökohtaiset asiasi (kieli, teema, etusivu, oma To Do) seuraavat sinua. Vain creator voi antaa tai poistaa oikeuden, ja tiimin esihenkilöt näkevät sinut Manager Panelin kohdassa "Esihenkilöt muista tiimeistä".' },
          'my-week': { title: 'Oma viikkoni etusivulla', where: 'Etusivu: kortti "Oma viikkoni" ylhäällä.', steps: ['Etsi etusivun yläosasta kortti "Oma viikkoni". Se näyttää oman viikkosi maanantaista sunnuntaihin, ja tämä päivä on korostettu.', 'Jokaisen päivän kohdalla näkyvät vuorosi (myös toistuvat), lomat, vapaapäivät ja perhevapaat, vielä hyväksymättömät lomapyynnöt (merkitty "odottaa"), sairauspoissaolo, etätyö, erääntyvät to-do-tehtävät ja tiimin to-do-tehtävät, tarkistettavat oppaat sekä parannukset, joilla on määräaika. Päivä ilman suunnitelmia näyttää viivan. Jos koko viikko on tyhjä, lukee "Ei suunnitelmia tällä viikolla".', 'Napsauta riviä päästäksesi suoraan oikeaan paikkaan: Vuorosuunnitelmaan, Kalenteriin, To Do -näkymään, Opaskirjastoon tai Parannuksiin.', 'Piilota kortti napsauttamalla "Muokkaa koontinäyttöä" ja kytkemällä "Oma viikkoni" pois. Siellä valitset myös koon: Pieni näyttää tämän päivän ja kaksi seuraavaa, Standardi koko viikon ja Suuri koko viikon tarkemmin.'], notes: 'Kortti näyttää vain omat asiasi, ei kollegoiden, eikä koskaan vuorojen kommentteja. Umpeutunut määräaika näytetään tälle päivälle ja merkitään "myöhässä". Kortti on aina ylimpänä, ja valinta tallennetaan omalle tilillesi.' },
          'morning-briefing': { title: 'Huberttin aamuyhteenveto', where: 'Hubert-chat (painike "Kysy Hubertilta" oikeassa alakulmassa).', steps: ['Avaa Hubert (painike "Kysy Hubertilta" oikeassa alakulmassa tai Ctrl+S) ensimmäisen kerran kunakin päivänä. Hubert lisää silloin itse lyhyen yhteenvedon keskustelun alkuun.', 'Yhteenvedossa näkyvät tämän päivän vuorosi (myös toistuvat), onko sinulla loma tai sairausloma tai teetkö etätyötä, omat ja tiimin to-do-tehtävät, jotka erääntyvät tänään tai ovat myöhässä, ketkä tiimissä ovat poissa tai etätyössä (vain nimet, ei koskaan syitä), tarkistettavat oppaat sekä parannukset, joilla on määräaika tällä viikolla. Tyhjät osiot jätetään pois.', 'Haluatko nähdä sen uudelleen, kirjoita Hubertille "huomenta" tai "mitä minulla on tänään?".'], notes: 'Yhteenveto näyttää vain omat asiasi ja tiimin poissaolot. Se näkyy automaattisesti enintään kerran päivässä omalla koneellasi.' },
          'customize-dashboard': { title: 'Mukauta etusivun koontinäyttöä', where: 'Etusivu: painike "Muokkaa koontinäyttöä".', steps: ['Napsauta etusivun yläosassa "Muokkaa koontinäyttöä".', 'Kytke haluamasi kortit päälle tai pois: Oma viikkoni, Tiimin tehtävät tänään, Tiimin tilanne tänään, High five -kiitokset, Poissa tänään, Päivän ateria, Sairaana tänään, Poissa Supply Chainissa, Etätöissä Supply Chainissa ja Sairaana Supply Chainissa.', 'Valitse kunkin kortin koko: Pieni, Standardi tai Suuri.', 'Napsauta "Valmis". "Nollaa" palauttaa oletusasetukset.'], notes: 'Valinta tallennetaan omalle tilillesi, eikä se vaikuta muihin.' },
          'since-last-time': { title: 'Ikkuna "Viime kerrasta lähtien"', where: 'Se avautuu itsestään, kun kirjaudut sisään.', steps: ['Jos edellisen käyntisi jälkeen on tapahtunut jotain, "Viime kerrasta lähtien" -ikkuna avautuu itsestään, kun kirjaudut sisään.', 'Se näyttää uudet sähköpostit, lomapyyntöjesi vastaukset, päivitetyt jaetut muistiinpanot ja uudet ilmoitukset.', 'Napsauta riviä päästäksesi suoraan oikeaan moduuliin tai sulje ikkuna.'], notes: 'Ikkuna katsoo taaksepäin enintään 30 päivää, eikä se avaudu, jos mitään uutta ei ole. Sitä ei näytetä ensimmäisellä kirjautumiskerralla.' },
          'whats-new': { title: 'Uutta päivityksen jälkeen', where: 'Se avautuu itsestään, kun käynnistät sovelluksen ensimmäisen kerran päivityksen jälkeen.', steps: ['Kun käynnistät sovelluksen ensimmäisen kerran päivityksen jälkeen, avautuu ikkuna "Mitä uutta Supply Chain Hubissa?". Se kertoo lyhyesti, mitä on uutta viimeksi näkemäsi version jälkeen.', 'Sulje se napsauttamalla "Hienoa, kiitos!".', 'Versionumero näkyy etusivun vasemmassa alakulmassa.'], notes: 'Ikkuna näytetään vain kerran tietokonetta kohden kunkin uuden version osalta.' },
        },
      },
      admin: {
        title: 'Hallintopaneeli',
        summary: 'Tiimin käyttäjien, työntekijöiden, tehtävätyyppien ja sairauspoissaolojen hallinta.',
        where: 'Avaa oikean yläkulman profiilivalikko ("Tilini") ja valitse "Hallintopaneeli". Se näkyy vain esihenkilöille.',
        tasks: {
          'admin-users': { title: 'Katso ja muokkaa käyttäjiä Hallintopaneelissa', steps: ['Avaa Hallintopaneeli ja valitse välilehti "Käyttäjät". Näet kaikki tiimin käyttäjät.', 'Vaihda käyttäjän rooli (käyttäjä tai esihenkilö) luettelossa.', 'Poista käyttäjä napsauttamalla "Poista käyttäjä". Sitä ei voi perua.'], notes: 'Creator-käyttäjän roolia ei voi muuttaa, eikä creator-käyttäjää voi poistaa.' },
          'admin-employees': { title: 'Lisää työntekijöitä ja tehtävätyyppejä Hallintopaneelissa', steps: ['Avaa Hallintopaneeli ja valitse välilehti "Työntekijät ja tehtävät".', 'Napsauta "Lisää työntekijä", kirjoita koko nimi, sähköposti, salasana ja rooli ja napsauta "Luo työntekijä". Sähköpostia ei voi muuttaa jälkeenpäin.', 'Napsauta "Lisää tehtävä" uutta tehtävätyyppiä varten: kirjoita nimi, valitse väri ja napsauta "Luo tehtävä". Tehtävän voi sitten määrittää Vaihtoaikataulussa.'], notes: 'Jos poistat tehtävän, kaikki siihen määritetyt vuorot poistetaan.' },
        },
      },
      creator: {
        title: 'Luojapaneeli',
        summary: 'Kaikkien tiimien hallinta: tiimien ja käyttäjien luominen, huipputulokset, sovelluspäivitykset ja tietojen tallennus.',
        where: 'Avaa oikean yläkulman profiilivalikko ("Tilini") ja valitse "Luojapaneeli". Se näkyy vain creatorille.',
        tasks: {
          'manage-teams': { title: 'Luo ja muokkaa tiimejä ja käyttäjiä', steps: ['Avaa Luojapaneeli ja valitse välilehti "Ryhmät". Kaikki rekisteröidyt tiimit näkyvät esihenkilöineen.', 'Napsauta "Luo tiimi", kirjoita tiimin nimi ja lyhyt koodi (kirjaimia ja numeroita, käytetään kansion nimenä) ja tallenna.', 'Napsauta "Muokkaa tiimiä" vaihtaaksesi nimen tai lyhenteen. Tiimin tietokansiota ei siirretä.', 'Napsauta "Luo käyttäjä", valitse tiimi, kirjoita nimi, sähköposti, koodi ja rooli ja napsauta "Luo käyttäjä".'] },
          'switch-team': { title: 'Vaihda tiimiä', steps: ['Paina Ctrl+K (Macilla Cmd+K).', 'Valitse "Vaihda kohteeseen: <tiimi>" kohdasta "Vaihtoryhmä". Päädyt valitun tiimin etusivulle.'], notes: 'Creator voi vaihtaa kaikkiin tiimeihin. Esihenkilöt, joilla on pääsy useaan hubiin, vaihtavat kohdasta "Vaihda hubia".' },
          'cross-team-managers': { title: 'Tee henkilöstä esihenkilö muissa tiimeissä', steps: ['Avaa Luojapaneeli, välilehti "Ryhmät", ja etsi "Esihenkilöt tiimien välillä".', 'Napsauta "Lisää", hae henkilö nimellä tai sähköpostilla ja valitse tiimit, joissa hän on esihenkilö. Henkilön omaa tiimiä ei voi valita.', 'Napsauta "Tallenna". Kun henkilö kirjautuu seuraavan kerran, hän voi valita hubin.', 'Napsauta kynää muuttaaksesi tiimejä tai roskakoria poistaaksesi kaikki oikeudet.'], notes: 'Henkilö pysyy omassa tiimissään omalla salasanallaan eikä näy toisen tiimin listoilla. Jos poistat oikeuden, kun henkilö on hubissa, hänet ohjataan omaan tiimiinsä minuutin kuluessa.' },
          'edit-highscores': { title: 'Muokkaa tai poista huipputulos', steps: ['Avaa Luojapaneeli ja valitse välilehti "Arcade". Valitse peli.', 'Napsauta kynää tuloksen kohdalla muuttaaksesi pisteet tai tason ja napsauta "Tallenna muutokset".', 'Napsauta roskakoria ja vahvista poistaaksesi tuloksen. "Poista kaikki vanhat huipputulokset" tyhjentää vanhan pelversion huipputulokset.'], notes: 'Tuloksen poistamista ei voi perua.' },
          'publish-update': { title: 'Julkaise sovelluspäivitys', steps: ['Avaa Luojapaneeli ja valitse välilehti "Tietojen tallennus". Kohdassa "Sovelluspäivitykset" valitset uuden sovelluspaketin (.zip) ja kirjoitat versionumeron, esimerkiksi 1.2.1.', 'Kirjoita halutessasi julkaisutiedot, jotka näkyvät päivitysikkunassa, ja napsauta "Julkaise päivitys".', 'Kaikki asiakkaat saavat ilmoituksen 15 minuutin kuluessa. Kohdassa "Käyttäjän App-versiot" näet, mitä versiota kukin käyttäjä ajaa, ja voit pakottaa tietyn version.'] },
          'data-backup': { title: 'Tietokansio ja varmuuskopio', steps: ['Avaa Luojapaneeli ja valitse välilehti "Tietojen tallennus".', 'Kohdassa "Nykyinen tiedostokansio" näet, missä sovelluksen tiedot sijaitsevat. Napsauta "Valitse tiedostokansio..." osoittaaksesi kiinteän kansion, esimerkiksi verkkoasemalla.', 'Napsauta "Vie varmuuskopio" tallentaaksesi kaiken yhteen tiedostoon. "Tuo varmuuskopio..." ja "Palauta tiedot" palauttavat tiedot, ja samannimiset nykyiset tiedot korvataan.'], notes: 'Sovelluksen päivittäminen ei hävitä tietoja. Varmuuskopio on hyödyllinen, jos siirryt uudelle tietokoneelle.' },
        },
      },
      calendar: {
        tasks: {
          'single-day-off': { title: 'Pyydä yksittäistä vapaapäivää', steps: ['Avaa Kalenteri ja napsauta painiketta, jossa lukee "Pyydän vapaapäivää."', 'Valitse päivä. Vain arkipäivät voi valita, ja voit kirjoittaa kommentin.', 'Napsauta "Lähetä pyyntö".'], notes: 'Pyyntö menee tiimin esihenkilöille ja odottaa hyväksyntää, aivan kuten lomapyyntö.' },
        },
      },
      meals: {
        tasks: {
          'view-meal-plan': { title: 'Katso ateriasuunnitelma', steps: ['Avaa Ateriasuunnitelma. Viikon ruokalistat maanantaista perjantaihin näkyvät.', 'Vaihda viikkoa nuolilla tai napsauta "Siirry nykyiseen viikkoon" palataksesi tähän viikkoon.', 'Kohdassa "Aiemmat ateriasuunnitelmat" näet aiempien viikkojen ruokalistat.'], notes: 'Jos haluat vain tietää, mitä lounaaksi on, kysy minulta esimerkiksi «Mitä lounaaksi huomenna?».' },
          'edit-meal-plan': { title: 'Muokkaa ateriasuunnitelmaa', steps: ['Avaa Ateriasuunnitelma ja napsauta "Muokkaa ateriasuunnitelmaa".', 'Kirjoita kunkin päivän ruokalista maanantaista perjantaihin.', 'Napsauta "Tallenna". "Tyhjä viikko" tyhjentää koko viikon ruokalistan ja "Peruuta" hylkää muutokset.'], notes: 'Ateriasuunnitelma on tiimin yhteinen, ja kuka tahansa tiimissä voi muokata sitä.' },
        },
      },
      notebook: {
        tasks: {
          'edit-note': { title: 'Muokkaa, kiinnitä tai poista muistiinpano', steps: ['Avaa Muistikirja ja etsi muistiinpano kohdasta "Jaetut huomautukset" tai "Henkilökohtaiset muistiinpanot".', 'Napsauta kynää muokataksesi muistiinpanoa tai roskakoria poistaaksesi sen. Vahvistat poiston, eikä sitä voi perua.', 'Napsauta nastaa pitääksesi muistiinpanon luettelon alussa.'], notes: 'Vain muistiinpanon kirjoittaja voi muokata tai poistaa sen.' },
          'find-note': { title: 'Etsi muistiinpano', steps: ['Avaa Muistikirja ja kirjoita hakukenttään ("Etsi otsikon tai sisällön mukaan...").', 'Napsauta tunnistetta (tag) nähdäksesi vain muistiinpanot, joilla on se. Napsauta uudelleen poistaaksesi suodattimen.'], notes: 'Kun kollega muuttaa kirjoittamaasi jaettua muistiinpanoa, siitä tulee ilmoitus Hubin kelloon (Muistikirjalla ei ole omaa kelloa).' },
        },
      },
      email: {
        tasks: {
          'mail-folders': { title: 'Luo kansio ja siirrä viesti', steps: ['Avaa Sähköpostijärjestelmä ja napsauta plus-painiketta kohdan "Kansiot" vieressä vasemmassa valikossa.', 'Kirjoita kansion nimi, valitse väri ja tallenna.', 'Avaa viesti ja napsauta "Siirrä kansioon" laittaaksesi sen kansioon. Kansio näkyy valikossa kohdassa "Kansiot".'] },
          'mail-filter': { title: 'Suodata viestit päivämäärän tai lähettäjän mukaan', steps: ['Avaa Sähköpostijärjestelmä ja valitse saapuneet ("Sähköposti") tai "Lähetetty".', 'Käytä suodattimia "Valitse ajanjakso" (Kaikki, Tänään, Viime viikolla, Viime kuussa) ja "Valitse lähettäjä" (kohdassa Lähetetty "Valitse vastaanottaja").'] },
        },
      },
      team: {
        tasks: {
          'other-teams': { title: 'Katso kollegat muissa tiimeissä', steps: ['Avaa Ryhmän yleiskatsaus. Oma tiimisi on ylhäällä.', 'Alempana, kohdassa "Muut toimitusketjun tiimit", näet muiden tiimien jäsenet.'], notes: 'Näet vain, keitä he ovat. Muiden tiimien muistiinpanot ja tehtävät eivät ole avoinna sinulle, etkä voi avata heidän vuorolistaansa Hubissa – mutta voit kysyä minulta kollegan vuoroista, esim. «Mitä Frederik Torp tekee tällä viikolla?».' },
        },
      },
      guides: {
        tasks: {
          'manage-categories': { title: 'Hallitse oppaiden luokkia', steps: ['Avaa Opaskirjasto ja napsauta "Hallitse kategorioita".', 'Kirjoita nimi kohtaan "Lisää uusi luokka" tai muokkaa ja poista olemassa olevia luokkia.'], notes: 'Luokkaa "General" ei voi muokata tai poistaa, eikä käytössä olevaa luokkaa voi poistaa.' },
          'export-library': { title: 'Vie oppaiden kirjasto', steps: ['Avaa Opaskirjasto ja napsauta "Vie kirjasto".', 'Napsauta "Valitse kansio" ja osoita paikallinen kansio tai verkkoasema.', 'Napsauta "Vie kaikki oppaat". Jokainen opas tallennetaan Word-tiedostona (.docx) luokkakohtaiseen kansioon.'] },
        },
      },
      manager: {
        tasks: {
          'bulk-approve': { title: 'Hyväksy useita lomapyyntöjä kerralla', steps: ['Avaa Johtajapaneeli ja valitse välilehti "Pyynnöt".', 'Merkitse käsiteltävät pyynnöt tai napsauta "Valitse kaikki".', 'Napsauta valittujen hyväksymispainiketta ("Hyväksytty") tai hylkäyspainiketta ("Hylkää valittu"). Yksittäisen pyynnön voit käsitellä painikkeilla "Hyväksyvät" ja "Hylkää".'], notes: 'Työntekijät saavat päätöksestä automaattisesti ilmoituksen.' },
          'manage-vacations': { title: 'Katso, muokkaa ja poista lomia Lomakatsauksessa', steps: ['Avaa Johtajapaneeli ja valitse välilehti "Lomakatsaus".', 'Suodata valinnoilla "Kaikki", "Odotetaan" tai "Hyväksytty".', 'Napsauta muokkauspainiketta muuttaaksesi päivämääriä, kommenttia tai tyyppiä (loma tai perhevapaa). Poista napsauttamalla roskakoria ja vahvistamalla.', '"Apurahaloma/vapaapäivä" ylhäällä antaa työntekijälle lomaa tai vapaapäivän suoraan.'], notes: 'Työntekijälle ilmoitetaan, kun esihenkilö on muokannut tai poistanut lomaa.' },
          'manage-birthdays': { title: 'Kirjaa syntymäpäivä', steps: ['Avaa Johtajapaneeli ja valitse välilehti "Syntymäpäivät".', 'Napsauta työntekijää ja napsauta "Lisää syntymäpäivä". Valitse päivä ja tallenna.', 'Samassa paikassa voit muokata syntymäpäivää tai poistaa sen painikkeella "Poista syntymäpäivä".'], notes: 'Syntymäpäivä näkyy lomakalenterissa ja sitä juhlitaan automaattisesti sovelluksessa. Sen voi antaa myös uutta työntekijää luodessasi.' },
          'access-requests': { title: 'Käsittele muiden tiimien pääsypyynnöt', steps: ['Avaa Johtajapaneeli ja valitse välilehti "Opas".', 'Kohdissa "Oppaan käyttöpyynnöt" ja "Knowledge Base -käyttöpyynnöt" näet muiden tiimien odottavat pyynnöt.', 'Napsauta "Hyväksyvät" tai "Hylkää".'], notes: 'Hyväksyntä antaa kahden päivän pääsyn varsinaiseen sisältöön.' },
          'onboard-user': { title: 'Luo uusi työntekijä (onboarding)', steps: ['Avaa Johtajapaneeli, valitse välilehti "Lupa" ja napsauta "Aluksella".', 'Vaihe 1 (tili): kirjoita koko nimi, työsähköposti, puhelinnumero ja väliaikainen salasana (vähintään 6 merkkiä) ja valitse rooli.', 'Vaihe 2 (syntymäpäivä): valitse syntymäaika. Vaihe on valinnainen, ja sen voi ohittaa.', 'Vaihe 3 (vahvistus): tarkista tiedot ja napsauta "Luo työntekijä".'], notes: 'Tili hyväksytään automaattisesti, ja työntekijä saa tervetuloviestin Supply Chain Hubissa. Anna työntekijälle väliaikainen salasana.' },
          'offboard-user': { title: 'Poista työntekijä käytöstä (offboarding)', steps: ['Avaa Johtajapaneeli, valitse välilehti "Lupa" ja napsauta "Ohitus".', 'Valitse työntekijä. Näet esikatselun siitä, mitä siivotaan: tili, vuorot, syntymäpäivä ja avoimet lomapyynnöt.', 'Vahvista ja napsauta "Offboard-työntekijä". Sitä ei voi perua.'], notes: 'Loma- ja sairaushistoria säilyy. Työntekijä menettää pääsyn Supply Chain Hubiin, ja kaikki hänen vuoronsa poistetaan vaihtoaikataulusta.' },
        },
      },
    },
  },
  sv: {
    modules: {
      hub: {
        title: 'Startsidan',
        summary: 'Startsidan med modulrutorna, dagens översikt, inlägg från chefer och klockan med notiser.',
        where: 'Startsidan öppnas när du loggar in. Använd tillbaka-knappen eller Escape för att komma tillbaka till den.',
        tasks: {
          'read-announcements': { title: 'Läs eller dölj ett inlägg', where: 'Startsidan, överst ovanför modulrutorna.', steps: ['Inlägg från chefer står överst på startsidan, ovanför modulrutorna. De visar rubrik, text, avsändare och hur länge sedan de skrevs.', 'Klicka på krysset vid ett inlägg för att dölja det. Det döljs bara för dig och kommer inte tillbaka.', 'Har du varit borta en tid visar fönstret "Sedan sist" om det har kommit nya inlägg.'], notes: 'Bara chefer kan skriva nya inlägg och ta bort dem för alla. Inläggen är skilda från E-postsystem.' },
          'post-announcement': { title: 'Skriv ett inlägg till alla', where: 'Startsidan, överst ovanför modulrutorna.', steps: ['Klicka på "Nytt inlägg till alla" överst på startsidan. Knappen visas bara för chefer.', 'Skriv en rubrik och ett meddelande till alla medarbetare.', 'Klicka på "Publicera". Inlägget visas direkt för alla i teamet.'], notes: 'Du tar bort ett inlägg för alla med papperskorgen vid inlägget. Medarbetare kan bara dölja ett inlägg för sig själva.' },
          'notification-bell': { title: 'Notiser (klockan)', where: 'Klockan uppe till höger på startsidan.', steps: ['Klockan visar en siffra när något kräver din uppmärksamhet, till exempel nya mejl, uppdaterade anteckningar, svar om semester, guider som ska granskas, födelsedagar, att göra-uppgifter, förbättringsförslag, länkar att godkänna, high fives och Multiplayer-utmaningar.', 'Klicka på klockan för att se listan. Klicka på en rad för att gå direkt till rätt ställe i appen. Raden försvinner sedan från klockan.', 'Klicka på krysset vid en rad för att ta bort den, eller på "Rensa alla" för att ta bort hela listan. En borttagen notis kommer inte tillbaka. Står det "Du är helt ikapp" behöver inget din uppmärksamhet.'], notes: 'Alla notiser samlas här, även från Förbättringar och Multiplayer. Samma lista kan också visas som Windows-notis (profilmenyn > "Inställningar"). Är det fler än 9 står det "9+".' },
          'send-high-five': { title: 'Skicka en high five till en kollega', where: 'Startsidan: kortet "High fives".', steps: ['Hitta kortet "High fives" på startsidan och klicka på "Skicka high five".', 'Sök efter en kollega på namn eller team och välj personen. Du kan skicka till alla godkända kollegor i alla team, men inte till dig själv.', 'Välj en emoji och skriv ett kort meddelande på högst 200 tecken.', 'Klicka på "Skicka high five". Mottagaren får den i klockan (och som Windows-notis om det är påslaget).'], notes: 'Kortet visar de senaste high fives du har fått och de senaste i ditt team. Du kan skicka högst 20 high fives per timme. Kortet kan döljas under "Anpassa startsidan". Du kan också be Hubert, t.ex. «skicka en high five till Anne för hjälpen» – du bekräftar själv innan den skickas.' },
          'quick-navigation': { title: 'Byt modul med tangentbordet (Ctrl+K)', where: 'Var som helst i appen.', steps: ['Tryck Ctrl+K (Cmd+K på Mac). Tryck igen för att stänga.', 'Skriv i fältet "Sök i moduler, guider, kollegor, anteckningar…". Du kan söka bland moduler, guider, Knowledge Base-artiklar, länkar, kollegor, anteckningar, uppgifter, förbättringar och dina egna meddelanden. Resultaten är grupperade, och varje rad visar vad det är, till exempel "Guide · TCD" eller "Anteckning · delad".', 'Välj ett resultat med piltangenterna och tryck Enter (eller klicka). Då öppnas rätt plats: guiden eller artikeln, anteckningen, kollegan i Teamöversikt, uppgiften, förbättringen eller meddelandet. Väljer du en modul, till exempel Kalender eller Matsedel, öppnas modulen. "Hem" tar dig tillbaka till startsidan.'], notes: 'Du ser bara det du redan har tillgång till: dina egna privata anteckningar, uppgifter och meddelanden samt teamets delade anteckningar och guider. Chefer ser också Manager Panel och Admin Panel. En creator ser också Creator Panel och kan byta team under "Byt team". Escape stänger sökningen.' },
          'switch-hub': { title: 'Byt hub när du är chef i flera team', where: 'Startsidan: knappen "Byt hub" vid teamnamnet, profilmenyn uppe till höger eller Ctrl+K.', steps: ['Har du fått chefsbehörighet i andra team än ditt eget visas "Välj din hub" efter inloggningen. Klicka på "Öppna" vid den hub du vill arbeta i. Den du valde senast är markerad.', 'Vill du byta senare klickar du på "Byt hub" på startsidan eller i profilmenyn, eller trycker Ctrl+K och väljer "Byt till: <team>". Du behöver inte logga ut.', 'En röd siffra vid "Byt hub" visar hur många användar- och semesterförfrågningar som väntar på dig i dina andra hubbar.'], notes: 'I ett annat team än ditt eget är du chef med samma behörigheter som teamets egna chefer, men du syns inte i deras skiftschema, semesteröversikt eller teamlista. Dina personliga saker (språk, tema, startsida, egen To Do) följer med dig. Endast creator kan ge eller ta bort behörigheten, och teamets chefer ser dig under "Chefer från andra team" i Manager Panel.' },
          'my-week': { title: 'Min vecka på startsidan', where: 'Startsidan: kortet "Min vecka" överst.', steps: ['Hitta kortet "Min vecka" överst på startsidan. Det visar din egen vecka från måndag till söndag, och dagens datum är markerat.', 'Varje dag visar dina pass (även återkommande), semester, lediga dagar och föräldraledighet, semesteransökningar som inte är godkända än (markerade "väntar"), sjukanmälan, hemarbete, att göra-uppgifter och teamets uppgifter som förfaller, guider du ska granska samt förbättringar med en frist. En dag utan planer visar ett streck. Är hela veckan tom står det "Inga planer den här veckan".', 'Klicka på en rad för att gå direkt till rätt ställe: Passchemat, Kalendern, To Do, Guidebiblioteket eller Förbättringar.', 'Vill du dölja kortet, klicka på "Anpassa startsidan" och slå av "Min vecka". Där väljer du också storlek: Liten visar idag och de två följande dagarna, Normal hela veckan och Stor hela veckan med fler detaljer.'], notes: 'Kortet visar bara dina egna saker, inte kollegornas, och aldrig kommentarerna till passen. En frist som har gått ut visas på dagens datum och märks "försenad". Kortet ligger alltid överst, och ditt val sparas på ditt eget konto.' },
          'morning-briefing': { title: 'Huberts morgonbriefing', where: 'Hubert-chatten (knappen "Fråga Hubert" nere till höger).', steps: ['Öppna Hubert (knappen "Fråga Hubert" nere till höger, eller Ctrl+S) första gången varje dag. Då lägger Hubert själv en kort översikt överst i chatten.', 'Översikten visar dina pass idag (även återkommande), om du har semester, är sjuk eller jobbar hemifrån, dina egna och teamets att göra-uppgifter som förfaller idag eller är försenade, vem i teamet som är borta eller jobbar hemifrån (bara namn, aldrig orsaker), guider du ska granska och förbättringar med en frist den här veckan. Tomma delar utelämnas.', 'Vill du se den igen, skriv "godmorgon" eller "vad har jag idag?" till Hubert.'], notes: 'Översikten visar bara dina egna saker och teamets frånvaro. Den visas automatiskt högst en gång per dag på din egen dator.' },
          'customize-dashboard': { title: 'Anpassa startsidan', where: 'Startsidan: knappen "Anpassa startsidan".', steps: ['Klicka på "Anpassa startsidan" överst på startsidan.', 'Slå på eller av de kort du vill se: Min vecka, Teamets uppgifter idag, Teamstatus idag, High fives, Lediga idag, Dagens mat, Sjuka idag, Lediga i Supply Chain, Hemarbete i Supply Chain och Sjuka i Supply Chain.', 'Välj storlek för varje kort: Liten, Normal eller Stor.', 'Klicka på "Klar". "Återställ" återställer standardinställningen.'], notes: 'Ditt val sparas på ditt eget konto och påverkar ingen annan.' },
          'since-last-time': { title: 'Fönstret "Sedan sist"', where: 'Det öppnas av sig självt när du loggar in.', steps: ['Har något hänt sedan ditt senaste besök öppnas fönstret "Sedan sist" av sig självt när du loggar in.', 'Det visar nya mejl, svar på dina semesteransökningar, delade anteckningar som uppdaterats och nya inlägg.', 'Klicka på en rad för att gå direkt till rätt modul, eller stäng fönstret.'], notes: 'Fönstret tittar högst 30 dagar tillbaka, och finns det inget nytt öppnas det inte. Det visas inte första gången du loggar in.' },
          'whats-new': { title: 'Nyheter efter en uppdatering', where: 'Det öppnas av sig självt första gången du startar appen efter en uppdatering.', steps: ['Första gången du startar appen efter en uppdatering öppnas fönstret "Nyheter i Supply Chain Hub". Det visar kort vad som är nytt sedan den version du senast såg.', 'Klicka på "Toppen, tack!" för att stänga det.', 'Versionsnumret står nere till vänster på startsidan.'], notes: 'Fönstret visas bara en gång per dator för varje ny version.' },
        },
      },
      admin: {
        title: 'Admin Panel',
        summary: 'Administration av användare, medarbetare, uppgiftstyper och sjukanmälningar för teamet.',
        where: 'Öppna profilmenyn uppe till höger ("Mitt konto") och välj "Admin Panel". Den visas bara för chefer.',
        tasks: {
          'admin-users': { title: 'Se och ändra användare i Admin Panel', steps: ['Öppna Admin Panel och välj fliken "Användare". Där ser du alla användare i teamet.', 'Ändra en användares roll (användare eller chef) i listan.', 'Klicka på "Ta bort användare" för att ta bort en användare. Det kan inte ångras.'], notes: 'Creator-användarens roll kan inte ändras, och creator-användaren kan inte tas bort.' },
          'admin-employees': { title: 'Lägg till medarbetare och uppgiftstyper i Admin Panel', steps: ['Öppna Admin Panel och välj fliken "Medarbetare & uppgifter".', 'Klicka på "Lägg till medarbetare", skriv fullständigt namn, e-post, lösenord och roll och klicka på "Skapa medarbetare". E-postadressen kan inte ändras efteråt.', 'Klicka på "Lägg till uppgift" för en ny uppgiftstyp: skriv namnet, välj en färg och klicka på "Skapa uppgift". Uppgiften kan sedan tilldelas i Schema.'], notes: 'Tar du bort en uppgift tas alla pass som är tilldelade den bort.' },
        },
      },
      creator: {
        title: 'Creator Panel',
        summary: 'Hantering av alla team: skapa team och användare, highscores, appuppdateringar och datalagring.',
        where: 'Öppna profilmenyn uppe till höger ("Mitt konto") och välj "Creator Panel". Den visas bara för en creator.',
        tasks: {
          'manage-teams': { title: 'Skapa och ändra team och användare', steps: ['Öppna Creator Panel och välj fliken "Team". Alla registrerade team visas med sina chefer.', 'Klicka på "Skapa team", skriv teamnamn och en kort kod (bokstäver och siffror, används som mappnamn) och spara.', 'Klicka på "Redigera team" för att ändra namn eller förkortning. Teamets datamapp flyttas inte.', 'Klicka på "Skapa användare", välj team, skriv namn, e-post, kod och roll och klicka på "Skapa användare".'] },
          'switch-team': { title: 'Byt team', steps: ['Tryck Ctrl+K (Cmd+K på Mac).', 'Välj "Byt till: <team>" under "Byt team". Du hamnar på startsidan i det valda teamet.'], notes: 'En creator kan byta till alla team. Chefer med tillgång till flera hubbar byter under "Byt hub".' },
          'cross-team-managers': { title: 'Gör en person till chef i andra team', steps: ['Öppna Creator Panel, fliken "Team", och hitta "Chefer över teamgränser".', 'Klicka på "Lägg till", sök fram personen på namn eller e-post och bocka för de team personen ska vara chef i. Personens eget team kan inte väljas.', 'Klicka på "Spara". Nästa gång personen loggar in kan hen välja hub.', 'Klicka på pennan för att ändra team eller på papperskorgen för att ta bort all behörighet.'], notes: 'Personen stannar i sitt eget team med sitt eget lösenord och syns inte i det andra teamets listor. Tar du bort behörigheten medan personen är i hubben skickas hen hem till sitt eget team inom en minut.' },
          'edit-highscores': { title: 'Ändra eller ta bort en highscore', steps: ['Öppna Creator Panel och välj fliken "Arcade". Välj spelet.', 'Klicka på pennan vid ett resultat för att ändra poäng eller nivå och klicka på "Spara ändringar".', 'Klicka på papperskorgen och bekräfta för att ta bort resultatet. "Ta bort alla gamla highscores" rensar highscores från en gammal spelversion.'], notes: 'Det går inte att ångra att ett resultat tas bort.' },
          'publish-update': { title: 'Publicera en appuppdatering', steps: ['Öppna Creator Panel och välj fliken "Datalagring". Under "Appuppdateringar" väljer du det nya apppaketet (.zip) och skriver versionsnumret, till exempel 1.2.1.', 'Skriv vid behov versionsanteckningar, som visas i uppdateringsfönstret, och klicka på "Publicera uppdatering".', 'Alla klienter får besked inom 15 minuter. Under "Användarnas appversioner" ser du vilken version varje användare kör och kan tvinga ut en viss version.'] },
          'data-backup': { title: 'Datamapp och säkerhetskopia', steps: ['Öppna Creator Panel och välj fliken "Datalagring".', 'Under "Nuvarande datamapp" ser du var appens data ligger. Klicka på "Välj datamapp…" för att peka på en fast mapp, till exempel på en nätverksenhet.', 'Klicka på "Exportera säkerhetskopia" för att spara allt i en fil. "Importera säkerhetskopia…" och "Återställ data" lägger tillbaka data, och befintliga data med samma namn skrivs över.'], notes: 'Du förlorar inga data när du uppdaterar appen. En säkerhetskopia är bra om du ska flytta till en ny dator.' },
        },
      },
      calendar: {
        tasks: {
          'single-day-off': { title: 'Ansök om en enstaka ledig dag', steps: ['Öppna Kalender och klicka på "Ansök om ledig dag".', 'Välj datum. Bara vardagar kan väljas, och du kan skriva en kommentar.', 'Klicka på "Skicka ansökan".'], notes: 'Ansökan går till teamets chefer och väntar på godkännande, precis som en semesteransökan.' },
        },
      },
      meals: {
        tasks: {
          'view-meal-plan': { title: 'Se matsedeln', steps: ['Öppna Matsedel. Veckans menyer från måndag till fredag visas.', 'Byt vecka med pilarna, eller klicka på "Gå till aktuell vecka" för att hoppa tillbaka till den här veckan.', 'Under "Tidigare matsedlar" ser du menyer från tidigare veckor.'], notes: 'Vill du bara veta vad det är till lunch, fråga mig, till exempel «Vad är det för lunch imorgon?».' },
          'edit-meal-plan': { title: 'Redigera matsedeln', steps: ['Öppna Matsedel och klicka på "Redigera matsedel".', 'Skriv dagens meny för varje dag från måndag till fredag.', 'Klicka på "Spara". "Rensa vecka" tömmer hela veckans meny, och "Avbryt" kastar ändringarna.'], notes: 'Matsedeln är gemensam för teamet och kan redigeras av alla i teamet.' },
        },
      },
      notebook: {
        tasks: {
          'edit-note': { title: 'Redigera, fäst eller ta bort en anteckning', steps: ['Öppna Anteckningsbok och hitta anteckningen under "Delade anteckningar" eller "Personliga anteckningar".', 'Klicka på pennan för att redigera anteckningen eller papperskorgen för att ta bort den. Du bekräftar borttagningen, och den kan inte ångras.', 'Klicka på nålen för att behålla anteckningen överst i listan.'], notes: 'Bara den som har skrivit en anteckning kan redigera eller ta bort den.' },
          'find-note': { title: 'Hitta en anteckning', steps: ['Öppna Anteckningsbok och skriv i sökfältet ("Sök på rubrik eller innehåll...").', 'Klicka på en tagg för att bara visa anteckningar med den taggen. Klicka igen för att ta bort filtret.'], notes: 'När en kollega ändrar en delad anteckning som du har skrivit kommer det i klockan på Hubben (Anteckningsbok har ingen egen klocka).' },
        },
      },
      email: {
        tasks: {
          'mail-folders': { title: 'Skapa en mapp och flytta ett mejl', steps: ['Öppna E-postsystem och klicka på plusknappen bredvid "Mappar" i menyn till vänster.', 'Skriv mappnamnet, välj en färg och spara.', 'Öppna ett mejl och klicka på "Flytta till mapp" för att lägga det i en mapp. Mappen finns i menyn under "Mappar".'] },
          'mail-filter': { title: 'Filtrera mejl på datum eller avsändare', steps: ['Öppna E-postsystem och välj "Inkorg" eller "Skickat".', 'Använd filtren "Välj period" (Alla, Idag, Senaste veckan, Senaste månaden) och "Välj avsändare" (under Skickat "Välj mottagare").'] },
        },
      },
      team: {
        tasks: {
          'other-teams': { title: 'Se kollegor i andra team', steps: ['Öppna Teamöversikt. Ditt eget team står överst.', 'Längre ner, under "Andra team i Supply Chain", ser du medlemmarna i de andra teamen.'], notes: 'Du ser bara vilka de är. Andra teams anteckningar och uppgifter är inte öppna för dig, och du kan inte öppna deras schema i Hubben – men du kan fråga mig om en kollegas pass, t.ex. «Vad gör Frederik Torp den här veckan?».' },
        },
      },
      guides: {
        tasks: {
          'manage-categories': { title: 'Hantera guidekategorier', steps: ['Öppna Guidebibliotek och klicka på "Hantera kategorier".', 'Skriv ett namn under "Lägg till ny kategori", eller redigera och ta bort befintliga kategorier.'], notes: 'Kategorin "General" kan inte redigeras eller tas bort, och en kategori som används kan inte tas bort.' },
          'export-library': { title: 'Exportera guidebiblioteket', steps: ['Öppna Guidebibliotek och klicka på "Exportera bibliotek".', 'Klicka på "Välj mapp" och peka på en lokal mapp eller en nätverksenhet.', 'Klicka på "Exportera alla guider". Varje guide sparas som en Word-fil (.docx) i en mapp per kategori.'] },
        },
      },
      manager: {
        tasks: {
          'bulk-approve': { title: 'Godkänn flera semesterförfrågningar på en gång', steps: ['Öppna Manager Panel och välj fliken "Förfrågningar".', 'Markera de förfrågningar du vill hantera, eller klicka på "Markera alla".', 'Klicka på "Godkänn markerade" eller "Avslå markerade". Du kan också godkänna eller avslå en enskild förfrågan med "Godkänn" och "Avslå".'], notes: 'Medarbetarna får automatiskt besked om beslutet.' },
          'manage-vacations': { title: 'Se, ändra och ta bort semestrar i Semesteröversikt', steps: ['Öppna Manager Panel och välj fliken "Semesteröversikt".', 'Filtrera med "Alla", "Väntande" eller "Godkända".', 'Klicka på redigeringsknappen för att ändra datum, kommentar eller typ (semester eller föräldraledighet). Klicka på papperskorgen och bekräfta för att ta bort.', '"Bevilja semester/ledig dag" överst ger en medarbetare semester eller en ledig dag direkt.'], notes: 'Medarbetaren får besked när en chef har ändrat eller tagit bort en semester.' },
          'manage-birthdays': { title: 'Registrera en födelsedag', steps: ['Öppna Manager Panel och välj fliken "Födelsedagar".', 'Klicka på medarbetaren och klicka på "Lägg till födelsedag". Välj datum och spara.', 'På samma ställe kan du ändra en födelsedag eller ta bort den med "Ta bort födelsedag".'], notes: 'Födelsedagen visas i semesterkalendern och firas automatiskt i appen. Den kan också anges när du skapar en ny medarbetare.' },
          'access-requests': { title: 'Hantera åtkomstförfrågningar från andra team', steps: ['Öppna Manager Panel och välj fliken "Guideåtkomst".', 'Under "Förfrågningar om guideåtkomst" och "Förfrågningar om Knowledge Base-åtkomst" ser du de väntande förfrågningarna från andra team.', 'Klicka på "Godkänn" eller "Avslå".'], notes: 'Ett godkännande ger 2 dagars åtkomst till själva innehållet.' },
          'onboard-user': { title: 'Skapa en ny medarbetare (onboarding)', steps: ['Öppna Manager Panel, välj fliken "Behörigheter" och klicka på "Onboarding".', 'Steg 1 (konto): skriv fullständigt namn, arbets-e-post, telefon och ett tillfälligt lösenord (minst 6 tecken) och välj roll.', 'Steg 2 (födelsedag): välj födelsedatum. Steget är valfritt och kan hoppas över.', 'Steg 3 (bekräfta): kontrollera uppgifterna och klicka på "Skapa medarbetare".'], notes: 'Kontot godkänns automatiskt, och medarbetaren får ett välkomstmejl i Supply Chain Hub. Ge medarbetaren det tillfälliga lösenordet.' },
          'offboard-user': { title: 'Offboarda en medarbetare', steps: ['Öppna Manager Panel, välj fliken "Behörigheter" och klicka på "Offboarding".', 'Välj medarbetaren. Du får en förhandsgranskning av vad som städas bort: konto, passtilldelningar, födelsedag och väntande semesterförfrågningar.', 'Bekräfta och klicka på "Offboarda medarbetare". Det kan inte ångras.'], notes: 'Semester- och sjukhistoriken sparas. Medarbetaren förlorar åtkomsten till Supply Chain Hub, och alla pass tas bort från schemat.' },
        },
      },
    },
  },
}

module.exports = { MORE_LOCALIZED }
